@Test
fun `retry changes failure to content`() = runTest {
    val repository = FakeFeedRepository(
        results = ArrayDeque(listOf(Result.failure(Offline()), Result.success(items)))
    )
    val vm = FeedViewModel(repository)

    vm.retry()
    advanceUntilIdle()

    assertEquals(FeedUiState.Content(items), vm.uiState.value)
}

class FakeUserRepository : UserRepository {
    private val users = mutableMapOf<UserId, User>()
    var saveFailure: Throwable? = null

    override suspend fun save(user: User) {
        saveFailure?.let { throw it }
        users[user.id] = user
    }

    override suspend fun find(id: UserId): User? = users[id]
}

